package com.rulecraft.decisionops.versions.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="decision_version")
public class DecisionVersion {@Id private UUID id;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="project_id",nullable=false)private UUID projectId;@Column(name="decision_service_id",nullable=false)private UUID decisionServiceId;@Column(name="client_request_id",nullable=false)private UUID clientRequestId;@Column(name="version_number",nullable=false)private int versionNumber;@Column(nullable=false,length=160)private String label;@Column(length=1000)private String note;@Enumerated(EnumType.STRING)@Column(name="validation_status",nullable=false,length=16)private VersionValidationStatus validationStatus;@Column(nullable=false,length=64)private String fingerprint;@Column(name="snapshot_json",nullable=false,columnDefinition="text")private String snapshotJson;@Column(name="source_service_version",nullable=false)private long sourceServiceVersion;@Column(name="source_graph_version",nullable=false)private long sourceGraphVersion;@Column(name="captured_by",nullable=false)private UUID capturedBy;@Column(name="captured_at",nullable=false)private Instant capturedAt;protected DecisionVersion(){}public DecisionVersion(UUID tenantId,UUID projectId,UUID serviceId,UUID requestId,int number,String label,String note,VersionValidationStatus status,String fingerprint,String snapshot,long serviceVersion,long graphVersion,UUID actor,Instant now){this.id=UUID.randomUUID();this.tenantId=tenantId;this.projectId=projectId;this.decisionServiceId=serviceId;this.clientRequestId=requestId;this.versionNumber=number;this.label=label;this.note=note;this.validationStatus=status;this.fingerprint=fingerprint;this.snapshotJson=snapshot;this.sourceServiceVersion=serviceVersion;this.sourceGraphVersion=graphVersion;this.capturedBy=actor;this.capturedAt=now;}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getProjectId(){return projectId;}public UUID getDecisionServiceId(){return decisionServiceId;}public UUID getClientRequestId(){return clientRequestId;}public int getVersionNumber(){return versionNumber;}public String getLabel(){return label;}public String getNote(){return note;}public VersionValidationStatus getValidationStatus(){return validationStatus;}public String getFingerprint(){return fingerprint;}public String getSnapshotJson(){return snapshotJson;}public long getSourceServiceVersion(){return sourceServiceVersion;}public long getSourceGraphVersion(){return sourceGraphVersion;}public Instant getCapturedAt(){return capturedAt;}}
